def compute(vars):
    network_solutions_revenue = vars["v1"]
    total_revenue = vars["v2"]

    if total_revenue == 0:
        return None

    ratio = network_solutions_revenue / total_revenue
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "network_solutions_revenue": network_solutions_revenue,
            "total_revenue": total_revenue,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
